SELECT id, customer_id, order_date, status, total_amount
FROM orders
WHERE order_date >= DATE '2025-01-01' AND order_date < DATE '2025-02-01';

SELECT COALESCE(SUM(amount_spent), 0) AS total_january_2025_spend
FROM marketing_spend
WHERE month >= DATE '2025-01-01' AND month < DATE '2025-02-01';
